<!-- generated by studio，请勿手工修改。 -->
<template>
  <Dialog v-model="dialogVisible" title="查看账户支付状态" width="760">
    <el-descriptions v-loading="loading" :column="2" border>
      <el-descriptions-item label="用户名">
        {{ detail?.username ?? '-' }}
      </el-descriptions-item>
      <el-descriptions-item label="支付金额">
        {{ detail?.paymentAmount ?? '-' }}
      </el-descriptions-item>
      <el-descriptions-item label="支付时间">
        {{ detail?.paymentTime ? formatDate(new Date(detail.paymentTime)) : '-' }}
      </el-descriptions-item>
      <el-descriptions-item label="到期时间">
        {{ detail?.expirationTime ? formatDate(new Date(detail.expirationTime)) : '-' }}
      </el-descriptions-item>
      <el-descriptions-item label="订单编号">
        {{ detail?.orderNumber ?? '-' }}
      </el-descriptions-item>
      <el-descriptions-item label="账户类型">
        {{ detail?.accountType ?? '-' }}
      </el-descriptions-item>
      <el-descriptions-item label="业务描述">
        {{ detail?.businessDescription ?? '-' }}
      </el-descriptions-item>
      <el-descriptions-item label="订单支付状态">
        {{ detail?.orderPaymentStatus ?? '-' }}
      </el-descriptions-item>
    </el-descriptions>
  </Dialog>
</template>

<script setup lang="ts">
import { formatDate } from '@/utils/formatTime'
import * as BoxunAccountPaymentApi from './BoxunAccountPaymentApi'

type BoxunAccountPaymentDetail = Awaited<ReturnType<typeof BoxunAccountPaymentApi.getBoxunAccountPayment>>
type EntityId = string | number

defineOptions({ name: 'BoxunAccountPaymentDetail' })

const dialogVisible = ref(false)
const loading = ref(false)
const detail = ref<BoxunAccountPaymentDetail>()

const open = async (id: EntityId) => {
  detail.value = undefined
  dialogVisible.value = true
  loading.value = true
  try {
    detail.value = await BoxunAccountPaymentApi.getBoxunAccountPayment(id)
  } finally {
    loading.value = false
  }
}
defineExpose({ open })
</script>
